    const update = () => setModel({ ...(appsmith.model || {}) });
    update();
    if (typeof appsmith.onModelChange === "function") appsmith.onModelChange(update);
    const id = setInterval(update, 400);
    return () => clearInterval(id);
  }, []);

  const data = (model && model.data) || [];
  const search = ((model && model.search) || "").trim().toLowerCase();
  const activeOnly = !!(model && model.activeOnly);

  const rows = useMemo(() => {
    let list = data.filter(function (r) {
      // "Active users only" = enabled accounts (active flag), i.e. Active + Pending
      // badges; only Inactive (disabled) rows are hidden. Matches the UBM count.
      if (activeOnly && String(r.status) === "Inactive") return false;
      if (search) {
        const hay = (String(r.id) + " " + String(r.first_name == null ? "" : r.first_name) + " " + String(r.last_name == null ? "" : r.last_name) + " " + String(r.email == null ? "" : r.email) + " " + String(r.status == null ? "" : r.status) + " " + String(r.role == null ? "" : r.role)).toLowerCase();
        if (hay.indexOf(search) < 0) return false;
      }
      return true;
    });
    const lc = (v) => (v == null ? "" : String(v)).toLowerCase();
    list.sort(function (a, b) {
      // Default ordering mirrors the UBM Users endpoint:
      // multiSort = [{lastName, asc}, {roles, desc}] with firstName as a final tiebreaker.
      if (sortKey === "__multi__") {
        const ln = lc(a.last_name).localeCompare(lc(b.last_name));
        if (ln !== 0) return ln;
        const rr = lc(b.role).localeCompare(lc(a.role));
        if (rr !== 0) return rr;
        return lc(a.first_name).localeCompare(lc(b.first_name));
