    if (!Number.isFinite(p)) return;
    setPage(Math.max(1, Math.min(totalPages, Math.floor(p))));
  };
  const onGotoSubmit = (e) => {
    if (e.key === "Enter") { const n = parseInt(gotoVal, 10); if (!isNaN(n)) goToPage(n); setGotoVal(""); }
  };
  const openRow = (row) => {
    appsmith.updateModel({ selectedUserId: row.id });
  };

  if (model.isLoading) {
    return React.createElement("div", { className: "skel" }, "Loading users...");
  }

  const upActive = (k) => (sortKey === k && sortDir === "asc") || (sortKey === "__multi__" && k === "last_name");
  const dnActive = (k) => (sortKey === k && sortDir === "desc") || (sortKey === "__multi__" && k === "role");
