    React.createElement("span", { className: upActive(k) ? "active" : "" }, "\u25b2"),
    React.createElement("span", { className: dnActive(k) ? "active" : "" }, "\u25bc")
  );

  const statusCell = (s) => React.createElement("span", { className: "status" },
    React.createElement("span", { className: "dot", style: { background: STATUS_COLOR[s] || "var(--appsmith-theme-textSecondaryColor, #94a3b8)" } }),
    (s == null ? "" : s)
  );

